function(partnership, class, class_partnership)

local _ = import "mixcalc_v4";
local logic = afs.logic.main;

local value =
  if partnership.value == "Yes" && class.value == "A" then "a Class A exempted"
  else if partnership.value == "Yes" && class.value == "B" then "a Class B exempted"
  else if partnership.value == "Yes" && class.value == "N/A" then "an exempted"
  else if partnership.value == "No" && class.value == "A" then "a Class A"
  else if partnership.value == "No" && class.value == "B" then "a Class B"
  else if partnership.value == "No" && class.value == "N/A" then "a"
  else "";

std.flattenArrays([
  _.fill(value).apply(logic.class_partnership, ctx = class_partnership),
])

function(textbox7, textbox8)

local _ = import "mixcalc_v4";
local gr = import "gr_v2";
local logic = afs.logic.main;

local group(s) =
  local len = std.length(s);
  if len <= 3 then s
  else group(std.substr(s, 0, len - 3)) + ',' + std.substr(s, len - 3, 3);

local addCommas(numStr) =
  local parts = std.split(numStr, '.');
  local intPart = parts[0];
  local decPart = if std.length(parts) > 1 then '.' + parts[1] else '';
  local isNegative = std.startsWith(intPart, '-');
  local digits = if isNegative then std.substr(intPart, 1, std.length(intPart) - 1) else intPart;
  (if isNegative then '-' else '') + group(digits) + decPart;

local phrase =
  if textbox8.value == null then ''
  else 'representing a capital commitment totaling $' + addCommas(gr.forceStr(textbox8.value));

std.flattenArrays([
  _.fill(phrase).apply(logic.textbox7, ctx = textbox7),
])

function(percentage, textbox6, radio2)

local _ = import "mixcalc_v4";
