    condition: radio2.value == "all",
    disabled: false,
};
local r2 = {
    condition: radio2.value == "percentage",
    disabled: false,
};

local percentageStr =
    if percentage.value == null then '' else std.toString(percentage.value) + '%';

std.flattenArrays([
    _
        .fill("all", condition = r1.condition, disabled = r1.disabled)
        .fill(percentageStr, condition = r2.condition, disabled = r2.disabled)
        .apply(logic.textbox6, ctx = textbox6),
])

