find: function(criteria, array, key)
    std.filter(
        function(item) 
            if (std.isString(criteria)) then
                std.member(
                    std.map(
                        function(i) std.asciiLower(i),
                        std.split(item[key], "/")
                    ),
                    std.asciiLower(criteria)
                )
            else criteria == item[key]
        ,
        array
    )
,

findCountryByName: function(name = "")
    local country = self.find(
        name,
        COUNTRY,
        "name",
    );

    if std.length(country) > 0 then
        country[0]["alpha2"]
    else null
,
}

