    function(key, condition) atd.add(key, 'hide', condition),

  'disable':
     function(key, condition) atd.add(key, 'disable', condition),

  'fill':
    function(key, value) atd.add(key, 'value', value),

  'hideRep':
    function(rep, key, index, condition) atd.add(rep, ['value', index, key, 'hide'], condition),

  'disableRep':
    function(rep, key, index, condition) atd.add(rep, ['value', index, key, 'disable'], condition),

  'fillRep':
    function(rep, key, index, value) atd.add(rep, ['value', index, key, 'value'], value),

  'applyRep':
    function(func, reps) std.flattenArrays(std.mapWithIndex(func, reps)),

  'endsWith':
    function(arr, ele) if std.length(arr) == 0 then false else arr[std.length(arr) - 1] == ele,

  'purge':
    function(arr, elements) std.filter(function(ele) !std.member(elements, ele), arr),

  'endsWithOneOf':
    function(array, elements) std.length(std.filter(function(element) self.endsWith(array, element), elements)) > 0,

  'safeInt':
    function(s)
      local numStr = std.join("", std.filter(function(c) std.member("0123456789", c), std.stringChars(s)));
      if numStr == "" then 0 else std.parseInt(numStr),

  'getDayOfMonth':
    function(mm, yy)
      local m = self.safeInt(mm);
      local y = self.safeInt(yy);
      local MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
      if !(m > 0 && m <= 12) then
        0
      else if m != 2 then
        MONTH_DAYS[m - 1]
      else
        local isLeap = ((y % 4 == 0) && (y % 100 != 0)) || (y % 400 == 0);
        if isLeap then 29 else 28,

  'wrap':
    function(s) if s == '' then '' else s + ' ',

  'getOrElse':
    function(key, default) if key == null then default else key
}
